func:
// msg.payload is the raw file text, read by the preceding "file in" core
// node — no require('fs') needed at all. Function nodes run in a
// sandboxed context that does NOT expose Node.js's require() by default;
// this was the actual bug (not a version-drift issue like the ha-entity
// one — plain require() has never worked in a stock Function node).
msg.results = [];
let secrets = null;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    msg.results.push({ check: 'Config file', pass: false, detail: 'Could not read/parse /share/lucius_secrets.json: ' + e.message + ' (if this is a "file not found" style error from the file-in node itself rather than a JSON error, the path is wrong or the file does not exist yet)' });
}

if (secrets) {
    const required = ['godaddy_base_url', 'godaddy_api_sync_token', 'oura_client_id',
        'oura_client_secret', 'oura_access_token', 'oura_refresh_token',
        'influxdb_url', 'influxdb_org', 'influxdb_bucket', 'influxdb_token'];
    const missing = required.filter(k => !secrets[k] || String(secrets[k]).trim() === '');

    // Beyond "present" — catch placeholder text left over from
    // lucius_secrets.json.example, which is technically non-empty and
    // would otherwise pass silently. This is a real gap found live: an
    // unreplaced placeholder cost a long investigation because every
    // other check (including this one) reported healthy. Two checks:
    // (1) any leftover .example placeholder language, (2) the sync
    // token specifically should be exactly 64 hex characters, matching
    // the real generated format — anything else is not the real value.
    const placeholderMarkers = ['PASTE', 'YOUR ', ' HERE', 'EXAMPLE', 'CHANGE_ME', 'TODO'];
    const looksLikePlaceholder = (val) => {
        const upper = String(val).toUpperCase();
        return placeholderMarkers.some(marker => upper.includes(marker));
    };
    const placeholderKeys = required.filter(k => secrets[k] && looksLikePlaceholder(secrets[k]));

    const tokenVal = secrets['godaddy_api_sync_token'] || '';
    const tokenFormatOk = /^[a-f0-9]{64}$/i.test(tokenVal);

    if (missing.length) {
        msg.results.push({ check: 'Config file', pass: false, detail: 'Missing/empty keys: ' + missing.join(', ') });
    } else if (placeholderKeys.length) {
        msg.results.push({ check: 'Config file', pass: false, detail: 'These still contain placeholder text from the .example file, not real values: ' + placeholderKeys.join(', ') });
    } else if (!tokenFormatOk) {
        msg.results.push({ check: 'Config file', pass: false, detail: 'godaddy_api_sync_token is present but is ' + tokenVal.length + ' characters — the real value should be exactly 64 hex characters. Check it was pasted correctly and completely.' });
    } else {
        msg.results.push({ check: 'Config file', pass: true, detail: 'All ' + required.length + ' required keys present, no placeholder text detected, sync token format looks correct' });
    }
}

msg.secrets = secrets || {};

msg.url = 'https://clients3.google.com/generate_204';
msg.method = 'GET';
msg.headers = {};
return msg;

const code = msg.statusCode;
const pass = (code === 204 || code === 200);
msg.results.push({ check: 'Generic internet reachability', pass, detail: pass ? ('HTTP ' + code) : ('HTTP ' + code + ' or no response — check the HA box\'s own internet connection') });

const base = (msg.secrets.influxdb_url || '').replace(/\/$/, '');
if (!base) {
    msg.results.push({ check: 'InfluxDB reachability', pass: false, detail: 'influxdb_url not set in config — skipped' });
    msg.skip_influx = true;
} else {
    msg.url = base + '/health';
    msg.method = 'GET';
    msg.headers = {};
}
return msg;

if (!msg.skip_influx) {
    const code = msg.statusCode;
    const status = msg.payload && msg.payload.status;
    const pass = (code === 200 && status === 'pass');
    msg.results.push({ check: 'InfluxDB reachability', pass, detail: pass ? 'healthy' : ('HTTP ' + code + ', status=' + status + ' — check influxdb_url and that the add-on is running') });
}

// Deliberately NO Authorization header — Oura returns 401 for an
// unauthenticated request, which is actually the expected PASS result
// here: it proves the network/DNS/TLS path to Oura's servers works,
// without needing a real token for a pure reachability check (same
// reasoning used in godaddy/app/oura_test.php's connectivity test).
msg.url = 'https://api.ouraring.com/v2/usercollection/personal_info';
msg.method = 'GET';
msg.headers = {};
return msg;

const code = msg.statusCode;
// ANY real numeric status code = reached Oura's servers and got a real
// response = PASS for reachability purposes, regardless of which
// specific error code they use for an unauthenticated request (Oura
// returned 400 in practice, not the 401 originally assumed here — real
// testing found this, not documentation, so the check no longer guesses
// at a specific code at all). 0/undefined/no response = genuine
// network/DNS/TLS failure = the only real FAIL condition.
const pass = (typeof code === 'number' && code > 0);
let detail;
if (pass) detail = 'reached (HTTP ' + code + ' — some error status is expected here since no token was sent on purpose; what matters is that a real response came back at all)';
else detail = 'no response — DNS/network/TLS failure reaching api.ouraring.com';
msg.results.push({ check: 'Oura API reachability', pass, detail });

const base = (msg.secrets.godaddy_base_url || '').replace(/\/$/, '');
const token = msg.secrets.godaddy_api_sync_token;
if (!base || !token) {
    msg.results.push({ check: 'GoDaddy reachability', pass: false, detail: 'godaddy_base_url or godaddy_api_sync_token not set in config — skipped' });
    msg.skip_godaddy = true;
} else {
    msg.url = base + '/api/status.php';
    msg.method = 'GET';
    msg.headers = { 'Authorization': 'Bearer ' + token };
}
return msg;

if (!msg.skip_godaddy) {
    const code = msg.statusCode;
    if (code === 200 && msg.payload && msg.payload.version_in_sync !== undefined) {
        const inSync = msg.payload.version_in_sync;
        msg.results.push({
            check: 'GoDaddy reachability + auth',
            pass: true,
            detail: 'reached, token accepted, app version ' + msg.payload.app_version +
                    (inSync ? ' (schema in sync)' : ' — SCHEMA OUT OF SYNC, run sql/upgrade_from_2.0.0.sql on GoDaddy (safe to re-run)')
        });
    } else if (code === 401) {
        msg.results.push({ check: 'GoDaddy reachability + auth', pass: false, detail: 'reached GoDaddy, but token rejected (HTTP 401) — check godaddy_api_sync_token matches config.php\'s API_SYNC_TOKEN exactly' });
    } else if (!code) {
        msg.results.push({ check: 'GoDaddy reachability + auth', pass: false, detail: 'no response — check godaddy_base_url and that the site is up' });
    } else {
        msg.results.push({ check: 'GoDaddy reachability + auth', pass: false, detail: 'unexpected HTTP ' + code });
    }
}

// Final summary — one readable block for the debug sidebar.
const lines = msg.results.map(r => (r.pass ? '\u2705' : '\u274c') + '  ' + r.check + ' \u2014 ' + r.detail);
const allPass = msg.results.every(r => r.pass);
msg.payload = (allPass ? '=== ALL CHECKS PASSED ===\n' : '=== ' + msg.results.filter(r => !r.pass).length + ' CHECK(S) FAILED ===\n') + lines.join('\n');
msg.all_pass = allPass;
return msg;
